const body = $input.first().json.body || {};
const topic = body.topic || 'Навчальна тема';
const score = body.score ?? 0;
const total = body.total ?? 0;
const percent = body.percent ?? 0;
const mistakes = body.mistakes || [];

const mistakesText = mistakes.length > 0
  ? mistakes.map((m, i) => `${i + 1}. Питання: ${m.question}\n   Обрано студентом: ${m.user_answer || 'Не обрано'}\n   Правильно: ${m.correct_answer}`).join('\n\n')
  : 'Помилок не вказано.';

return [{
  json: {
    coach_mode: 'remedial',
    ollama_model: body.ollama_model || 'qwen3.5:4b',
    system_prompt: 'Ти — доброзичливий AI Study Coach університету. Пиши виключно чистою українською мовою у форматі Markdown. Склади структуровану, коротку і практичну шпаргалку для підготовки.',
    user_prompt: `Студент пройшов тест з теми "${topic}" з результатом ${score}/${total} (${percent}%).\n\nПитання, де були помилки:\n${mistakesText}\n\nЗавдання:\n1. Коротко поясни кожну помилку простими словами.\n2. Склади стислу шпаргалку (ключові тези та правила по цих слабких місцях), щоб студент легко повторив тему.`
  }
}];

const body = $input.first().json.body || {};
const topic = body.topic || 'Навчальна тема';
const score = body.score ?? 0;
const total = body.total ?? 0;
const percent = body.percent ?? 0;
const mistakes = body.mistakes || [];

const mistakesNote = mistakes.length > 0
  ? '\nНевеликі неточності:\n' + mistakes.map((m, i) => `${i + 1}. ${m.question} -> Правильно: ${m.correct_answer}`).join('\n')
  : '';

return [{
  json: {
    coach_mode: 'advanced',
    ollama_model: body.ollama_model || 'qwen3.5:4b',
    system_prompt: 'Ти — AI Study Coach університету. Пиши виключно чистою українською мовою у форматі Markdown.',
    user_prompt: `Студент чудово пройшов тест з теми "${topic}" із результатом ${score}/${total} (${percent}%).${mistakesNote}\n\nЗавдання:\n1. Коротко похвали за гарний результат і зафіксуй 3-4 ключові тези теми у форматі шпаргалки.${mistakes.length > 0 ? '\n2. Поясни ті дрібні помилки, що трапилися.' : ''}\n3. Запропонуй 1 цікаве поглиблене питання для самостійного роздуму (без варіантів відповіді, з короткою підказкою).`
  }
}];

const webhookBody = $('Webhook Trigger').first().json.body || {};
const percent = Number(webhookBody.percent ?? 100);
const coachMode = percent < 70 ? 'remedial' : 'advanced';
const content = ($input.first().json.message && $input.first().json.message.content) || '';

return [{
  json: {
    status: 'success',
    source: `n8n AI Study Coach (${webhookBody.ollama_model || 'qwen3.5:4b'})`,
    coach_mode: coachMode,
    study_note_md: content.trim()
  }
}];
